import net from 'net';

function normalizeIPv4(ip) {
  // Remove leading zeros from each octet
  return ip.split('.').map(octet => String(Number(octet))).join('.');
}

function isPrivateIPv4(ip) {
  if (!net.isIPv4(ip)) return false;
  const normalizedIp = normalizeIPv4(ip);
  const parts = normalizedIp.split('.').map(Number);
  // 10.0.0.0/8
  if (parts[0] === 10) return true;
  // 172.16.0.0/12
  if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
  // 192.168.0.0/16
  if (parts[0] === 192 && parts[1] === 168) return true;
  // 127.0.0.0/8 (loopback)
  if (parts[0] === 127) return true;
  // 169.254.0.0/16 (link-local)
  if (parts[0] === 169 && parts[1] === 254) return true;
  // 100.64.0.0/10 (Carrier-grade NAT)
  if (parts[0] === 100 && parts[1] >= 64 && parts[1] <= 127) return true;
  // 192.0.0.0/24 (IETF Protocol Assignments)
  if (parts[0] === 192 && parts[1] === 0 && parts[2] === 0) return true;
  // 192.0.2.0/24 (TEST-NET-1)
  if (parts[0] === 192 && parts[1] === 0 && parts[2] === 2) return true;
  // 192.31.196.0/24 (ARIN reserved)
  if (parts[0] === 192 && parts[1] === 31 && parts[2] === 196) return true;
  // 192.52.193.0/24 (ARIN reserved)
  if (parts[0] === 192 && parts[1] === 52 && parts[2] === 193) return true;
  // 192.88.99.0/24 (deprecated 6to4 relay)
  if (parts[0] === 192 && parts[1] === 88 && parts[2] === 99) return true;
  // 192.175.48.0/24 (Direct Delegation AS112)
  if (parts[0] === 192 && parts[1] === 175 && parts[2] === 48) return true;
  // 198.18.0.0/15 (benchmarking)
  if (parts[0] === 198 && (parts[1] === 18 || parts[1] === 19)) return true;
  // 198.51.100.0/24 (TEST-NET-2)
  if (parts[0] === 198 && parts[1] === 51 && parts[2] === 100) return true;
  // 203.0.113.0/24 (TEST-NET-3)
  if (parts[0] === 203 && parts[1] === 0 && parts[2] === 113) return true;
  // 240.0.0.0/4 (reserved for future use)
  if (parts[0] >= 240 && parts[0] <= 255) return true;
  // 255.255.255.255 (broadcast)
  if (normalizedIp === '255.255.255.255') return true;
  // 0.0.0.0/8 (reserved)
  if (parts[0] === 0) return true;
