var required = require('requires-port')
  , qs = require('querystringify')
  , CRHTLF = /[\n\r\t]/g
  , slashes = /^[A-Za-z][A-Za-z0-9+-.]*:\/\//
  , protocolre = /^([a-z][a-z0-9.+-]*:)?(\/\/)?([\\/]+)?([\S\s]*)/i
  , windowsDriveLetter = /^[a-zA-Z]:/
  , whitespace = /^[ \f\n\r\t\v\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]+/;

/**
 * Securely parse a URL and extract its components.
 * This patch adds input validation and strict protocol/resource handling to prevent authorization bypass.
 */
function secureParseUrl(url) {
  if (typeof url !== 'string' || !url.trim()) {
    throw new Error('Invalid URL input');
  }
  url = url.trim().replace(CRHTLF, '');
  let output = {
    protocols: [],
    protocol: null,
    port: null,
    resource: '',
    user: '',
    pathname: '',
    hash: '',
    search: '',
    href: url,
    query: Object.create(null)
  };
  try {
    // Use the standard URL parser for strict parsing
    const parsed = new URL(url);
    output.protocols = [parsed.protocol.replace(':', '')];
    output.protocol = output.protocols[0];
    output.port = parsed.port ? Number(parsed.port) : null;
    if (output.port !== null && (isNaN(output.port) || output.port < 0 || output.port > 65535)) {
      output.port = null;
    }
    output.resource = parsed.hostname;
    output.user = parsed.username || '';
    output.pathname = parsed.pathname;
    output.hash = parsed.hash ? parsed.hash.slice(1) : '';
    output.search = parsed.search ? parsed.search.slice(1) : '';
    output.href = parsed.href;
    output.query = qs.parse(output.search);
    // Security check: restrict sensitive protocols
    if (output.protocol === 'file' || output.protocol === 'ssh') {
      // Only allow if explicitly permitted (customize as needed)
      // For demonstration, we block these protocols
      throw new Error('Access to sensitive protocol is not allowed');
    }
  } catch (e) {
    // Fallback for non-standard URLs (e.g., local file paths)
    output.protocols = ['file'];
    output.protocol = 'file';
    output.port = null;
    output.resource = '';
    output.user = '';
    output.pathname = url;
    output.hash = '';
    output.search = '';
    output.href = url;
    output.query = Object.create(null);
  }
  return output;
}

