patch:
func isOriginAllowed(allows []string, origin string) bool {
	for _, o := range allows {
		if o == allOrigins {
			return true
		}

		// Parse the origin to extract the host
		u, err := url.Parse(origin)
		if err != nil {
			continue
		}
		host := u.Hostname()

		// Exact match
		if host == o {
			return true
		}

		// Subdomain match: allow *.example.com for o == example.com
		if strings.HasPrefix(host, ".") {
			// Defensive: host should not start with a dot
			continue
		}
		if len(host) > len(o)+1 && strings.HasSuffix(host, "."+o) {
			return true
		}
	}

	return false
}

