var (
	// ErrNeedsLogin means the user should be redirected to the login page
	ErrNeedsLogin = errors.New("redirect to login page")

	// Used to check final redirects are not susceptible to open redirects.
	// Matches //, /\ and both of these with whitespace in between (eg / / or / \).
	invalidRedirectRegex = regexp.MustCompile(`^/(\s|\v)?(/|\\)`)
)

// isValidRedirect checks if the redirect URL is safe (relative or matches trusted host)
func isValidRedirect(redirectURL string, trustedHost string) bool {
	if invalidRedirectRegex.MatchString(redirectURL) {
		return false
	}

	u, err := url.Parse(redirectURL)
	if err != nil {
		return false
	}

	// Allow only relative URLs (no scheme, no host)
	if u.Scheme == "" && u.Host == "" {
		return true
