			})
		})
	}
	// --- PATCH END ---

	return &service{
		server:        openFgaServer,
		grpcAddr:      grpcAddr,
		httpAddr:      httpAddr,
		datastore:     datastore,
		authenticator: authenticator,
	}, nil
}

