// isSafeGitURL checks that the URL is safe for use in git commands
func isSafeGitURL(u *url.URL) bool {
	if u == nil {
		return false
	}
	switch u.Scheme {
	case "http", "https", "git", "ssh":
		return true
	default:
		return false
	}
}

// isSafeGitRef checks that the ref is a valid branch, tag, or commit
func isSafeGitRef(ref string) bool {
	if ref == "" {
		return true
	}
	// Only allow refs that match branch, tag, or commit patterns
	if gitCommitIDRegex.MatchString(ref) {
		return true
	}
	// Disallow refs with suspicious characters
	if strings.ContainsAny(ref, "\n\r\0 	/\\:") {
		return false
	}
	return true
}

