		return fmt.Errorf("Failed to uncompress slug: %v", err)
	}

	// Untar as we read.
	untar := tar.NewReader(uncompressed)

	// Canonicalize the destination directory
	absDst, err := filepath.Abs(dst)
	if err != nil {
		return fmt.Errorf("Failed to get absolute path of destination: %v", err)
	}

	// Helper to check if any parent in the path is a symlink
	isThroughSymlink := func(path string) (bool, string, error) {
		rel, err := filepath.Rel(absDst, path)
		if err != nil {
			return false, "", err
		}
		parts := strings.Split(rel, string(os.PathSeparator))
		cur := absDst
		for _, p := range parts[:len(parts)-1] { // exclude the file itself
			cur = filepath.Join(cur, p)
			fi, err := os.Lstat(cur)
			if err != nil {
				if os.IsNotExist(err) {
					continue // not created yet
				}
				return false, "", err
			}
			if fi.Mode()&os.ModeSymlink != 0 {
				linkTarget, err := os.Readlink(cur)
				if err != nil {
					return false, "", err
				}
				resolved := linkTarget
				if !filepath.IsAbs(linkTarget) {
					resolved = filepath.Join(filepath.Dir(cur), linkTarget)
				}
				resolved, err = filepath.Abs(resolved)
				if err != nil {
					return false, "", err
				}
				if !strings.HasPrefix(resolved+string(os.PathSeparator), absDst+string(os.PathSeparator)) && resolved != absDst {
					return true, cur, nil
				}
			}
		}
		return false, "", nil
	}

	for {
		header, err := untar.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("Failed to untar slug: %v", err)
		}

