		if throughSymlink, symlinkPath, err := isThroughSymlink(absPath); err != nil {
			return fmt.Errorf("Failed checking symlink in path %q: %v", absPath, err)
		} else if throughSymlink {
			return fmt.Errorf("Cannot extract %q through symlink %q", path, symlinkPath)
		}

		// Make the directories to the path.
		dir := filepath.Dir(absPath)
		if err := os.MkdirAll(dir, 0755); err != nil {
			return fmt.Errorf("Failed to create directory %q: %v", dir, err)
		}

		// Handle symlinks.
		if header.Typeflag == tar.TypeSymlink {
