	isThroughSymlink := func(path string) (bool, string, error) {
		rel, err := filepath.Rel(absDst, path)
		if err != nil {
			return false, "", err
		}
		parts := strings.Split(rel, string(os.PathSeparator))
		cur := absDst
		for _, p := range parts[:len(parts)-1] { // exclude the file itself
			cur = filepath.Join(cur, p)
			fi, err := os.Lstat(cur)
			if err != nil {
				if os.IsNotExist(err) {
					continue // not created yet
				}
				return false, "", err
			}
			if fi.Mode()&os.ModeSymlink != 0 {
				linkTarget, err := os.Readlink(cur)
				if err != nil {
					return false, "", err
				}
