				if !filepath.IsAbs(linkTarget) {
					resolved = filepath.Join(filepath.Dir(cur), linkTarget)
				}
				resolved, err = filepath.Abs(resolved)
				if err != nil {
					return false, "", err
				}
				if !strings.HasPrefix(resolved+string(os.PathSeparator), absDst+string(os.PathSeparator)) && resolved != absDst {
					return true, cur, nil
				}
			}
		}
		return false, "", nil
	}

