		header, err := untar.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("Failed to untar slug: %v", err)
		}

		// Get rid of absolute paths.
		path := header.Name
		if len(path) > 0 && path[0] == '/' {
			path = path[1:]
		}
		cleanPath := filepath.Clean(path)
		absPath := filepath.Join(absDst, cleanPath)
		absPath, err = filepath.Abs(absPath)
		if err != nil {
			return fmt.Errorf("Failed to get absolute path for %q: %v", absPath, err)
		}

		// Ensure the final path is within the destination directory
		if !strings.HasPrefix(absPath+string(os.PathSeparator), absDst+string(os.PathSeparator)) && absPath != absDst {
			return fmt.Errorf("Invalid file path %q: outside of destination directory", absPath)
		}

