        var reqUrl = req.url.replace(/(\.\.\/?)/g, '');

        var uri = url.parse(reqUrl).pathname,
            filename = path.join(root, uri);

        if (uri.charAt(uri.length - 1) === '/') {
            filename += 'index.html';
        }

