module.exports = function(path, opts, cb) {
  if (!cb) {
    cb = opts;
    opts = {};
  }

  // Sanitize path to prevent command injection
  if (typeof path !== 'string' || /[;&|`$><]/.test(path)) {
    return cb(new Error('Invalid path input'));
  }

  var cmdArgs = module.exports.cmd(path, opts);
  opts.timeout = opts.timeout || 5000;

  // Use execFile for safer execution
  const execFile = require('child_process').execFile;
  execFile(cmdArgs[0], cmdArgs.slice(1), opts, function(e, stdout, stderr) {
    if (e) { return cb(e); }
    if (stderr) { return cb(new Error(stderr)); }

    return cb(null, module.exports.parse(path, stdout, opts));
  });
};

