function diskusage(path, cb) {
    if (typeof path !== 'string' || path.indexOf('"') !== -1 || path.indexOf('\0') !== -1) {
        return cb(new Error('Invalid path: paths with double quotes or null bytes are not supported'));
    }

    // Use execFile for safe argument passing
    execFile('df', ['-k', path], function(err, stdout) {
        if (err) {
            return cb(err);
        }

        try {
            cb(null, parse(stdout));
        } catch (e) {
            cb(e);
        }
    });
}

