exports.killByPort = function (port) {
  var processId = null;
  // Validate port is a number and in valid range
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return;
  }
  const { execFileSync } = require('child_process');
  try {
    // Use execFileSync to avoid shell injection
    var output = execFileSync('lsof', ['-t', '-i:' + port], { encoding: 'utf8' });
    // Extract the first line as process ID and ensure it's a number
    var lines = output.trim().split('\n');
    if (lines.length > 0 && /^\d+$/.test(lines[0])) {
      processId = lines[0];
    }
  } catch (e) {
    // Ignore errors
  }

  if (processId !== null) { // if exists kill
    try {
      execFileSync('kill', [processId]);
    } catch (e) {
      // Ignore errors
    }
  }
}

