          'Content-Type': mime_types[path_tools.extname('pixel.gif')] || 'image/gif'
        });
        return res.end(new Buffer(unescape(escaped_pixel_gif), 'binary'));
      } else {
        return dispatch._404(null, res, pathname);
      }
    }
  });
};

