			return fmt.Errorf("unable to resolve destination directory: %w", err)
		}
		absTarget, err := filepath.Abs(target)
		if err != nil {
			return fmt.Errorf("unable to resolve target path: %w", err)
		}
		if !strings.HasPrefix(absTarget, absDst+string(os.PathSeparator)) && absTarget != absDst {
