def secure_join(root, *paths):
    "Join paths and ensure it still below root"
    root = os.path.abspath(os.path.realpath(root))
    path = os.path.abspath(os.path.realpath(os.path.join(root, *paths)))
    # Ensure root ends with separator for strict prefix check
    if not root.endswith(os.sep):
        root = root + os.sep
    if not path.startswith(root):
        raise IOError("Permission denied: %s" % path)
    return path

