    order,
    limit: filters.$limit,
    offset: filters.$skip,
    raw: this.raw,
    distinct: true
  }, params.sequelize);

  if (filters.$select) {
    q.attributes = filters.$select.map(select => `${select}`);
  }

  const Model = this.applyScope(params);

  // Until Sequelize fix all the findAndCount issues, a few 'hacks' are needed to get the total count correct

