getInfo: function () {
  var self = this;
  var getInfoCmdArr = this.constructGetInfoCommand();
  var promise = new Promise(function (resolve, reject) {
    // Use spawn to avoid shell interpretation and injection
    var child = require('child_process').spawn(getInfoCmdArr[0], [getInfoCmdArr[1]]);
    var stdout = '';
    var stderr = '';
    child.stdout.on('data', function (data) {
      stdout += data;
    });
    child.stderr.on('data', function (data) {
      stderr += data;
    });
    child.on('error', function (err) {
      return reject({
        message: "Failed to get PDF'S information",
        error: err,
        stdout: stdout,
        stderr: stderr
      });
    });
    child.on('close', function (code) {
      if (code !== 0) {
        return reject({
          message: "Failed to get PDF'S information",
          error: new Error('Process exited with code ' + code),
          stdout: stdout,
          stderr: stderr
        });
      }
      return resolve(self.parseGetInfoCommandOutput(stdout));
    });
  });
  return promise;
},

