module.exports = function (msg, silent) {
	var arg = '';

	msg = makeDefault(msg);

	if (silent === undefined) {
		silent = true;
	}

	function isSafe(str) {
		// Reject dangerous shell metacharacters
		return !/[;&|`$()<>\\]/.test(str);
	}

	var messages = Array.isArray(msg) ? msg : [msg];
	var safeArgs = [];
	if (messages.length) {
		messages.forEach(function (m) {
			m = makeDefault(m);
			if (!isSafe(m)) {
				throw new Error('Unsafe commit message detected');
			}
			safeArgs.push('-m', m);
		});
	} else {
		if (!isSafe(defaultMsg)) {
			throw new Error('Unsafe default commit message detected');
		}
		safeArgs.push('-m', defaultMsg);
	}

	// Use shell.exec with array arguments if supported, otherwise join safely
	var execArgs = ['commit'].concat(safeArgs, ['--allow-empty', '--no-gpg-sign']);
	shell.exec('git', execArgs, {
		silent: silent
	});
};

