  // For Grunt, allow copying anywhere unless options.restrictToCwd is true
  if (options && options.restrictToCwd) {
    var baseDir = process.cwd();
    if (!resolvedSrc.startsWith(baseDir) || !resolvedDest.startsWith(baseDir)) {
      throw new Error('Invalid path: Path traversal detected.');
    }
  }

  // Handle symlinks safely
  var stat = fs.lstatSync(resolvedSrc);
  if (stat.isSymbolicLink()) {
    var realSrc = fs.realpathSync(resolvedSrc);
    if (options && options.restrictToCwd) {
      var baseDir = process.cwd();
      if (!realSrc.startsWith(baseDir)) {
        throw new Error('Invalid symlink: Path traversal detected.');
      }
    }
    resolvedSrc = realSrc;
  }

  if (file.isDir(resolvedSrc)) {
    // Copy a directory, recursively.
    // Explicitly create new dest directory.
    file.mkdir(resolvedDest);
    // Iterate over all sub-files/dirs, recursing.
    fs.readdirSync(resolvedSrc).forEach(function(filepath) {
      var childSrc = path.join(resolvedSrc, filepath);
      var childDest = path.join(resolvedDest, filepath);
      copy(childSrc, childDest, options);
    });
  } else {
    // Copy a single file.
    file._copy(resolvedSrc, resolvedDest, options);
  }
};

