  // Normalize and resolve paths
  var resolvedSrc = path.resolve(srcpath);
  var resolvedDest = path.resolve(destpath);

  // Prevent path traversal: ensure no '..' segments after normalization
  function hasPathTraversal(p) {
    var rel = path.relative(process.cwd(), p);
    return rel.split(path.sep).includes('..');
  }
  if (hasPathTraversal(resolvedSrc) || hasPathTraversal(resolvedDest)) {
    throw new Error('Invalid path: Path traversal detected.');
  }

  // Handle symlinks safely
  var stat;
  try {
    stat = fs.lstatSync(resolvedSrc);
  } catch (e) {
    throw new Error('Source path does not exist: ' + srcpath);
  }
  if (stat.isSymbolicLink()) {
    var realSrc = fs.realpathSync(resolvedSrc);
    if (hasPathTraversal(realSrc)) {
      throw new Error('Invalid symlink: Path traversal detected.');
    }
    resolvedSrc = realSrc;
    stat = fs.statSync(resolvedSrc);
  }

  // Prevent copying special files (e.g., device files)
  if (!stat.isFile() && !stat.isDirectory()) {
    throw new Error('Invalid source: Not a regular file or directory.');
  }

  if (file.isDir(resolvedSrc)) {
    // Copy a directory, recursively.
    // Explicitly create new dest directory.
