	if filepath.IsAbs(filePath) {
		return "", fmt.Errorf("bodyFile contains absolute path (%s). only relative is supported", filePath)
	}

	// Clean the user-supplied path
	cleanedPath := filepath.Clean(filePath)
	fullPath := filepath.Join(hf.Cfg.ResponsesBodyFilesPath, cleanedPath)

	// Ensure the final path is within the base directory
	basePath, err := filepath.Abs(hf.Cfg.ResponsesBodyFilesPath)
	if err != nil {
		return "", fmt.Errorf("failed to resolve base path: %w", err)
	}
	absFullPath, err := filepath.Abs(fullPath)
	if err != nil {
		return "", fmt.Errorf("failed to resolve file path: %w", err)
	}
	if !strings.HasPrefix(absFullPath, basePath+string(os.PathSeparator)) && absFullPath != basePath {
		return "", fmt.Errorf("bodyFile path escapes base directory: %s", filePath)
	}

	fileContents, err := ioutil.ReadFile(fullPath)
	if err != nil {
		return "", err
	}

	return string(fileContents[:]), nil
}

