_resolvePath(path = '.') {
  // Normalize path separators for cross-platform compatibility
  path = path.replace(/\\/g, '/');
  const clientPath = (() => {
    path = nodePath.normalize(path);
    if (nodePath.isAbsolute(path)) {
      return nodePath.join(path);
    } else {
      return nodePath.join(this.cwd, path);
    }
  })();

  const fsPath = (() => {
    const resolvedPath = nodePath.join(this.root, clientPath);
    const normalizedFsPath = nodePath.resolve(nodePath.normalize(nodePath.join(resolvedPath)));
    // Ensure fsPath is within this.root
    const relative = nodePath.relative(this.root, normalizedFsPath);
    if (relative.startsWith('..') || nodePath.isAbsolute(relative)) {
      // Path traversal detected, restrict to root
      return this.root;
    }
    return normalizedFsPath;
  })();

  return {
    clientPath,
    fsPath
  };
}

