func WithAdditionalGIDs(userstr string) SpecOpts {
	return func(ctx context.Context, client Client, c *containers.Container, s *Spec) (err error) {
		// For LCOW or on Darwin additional GID's not supported
		if s.Windows != nil || runtime.GOOS == "darwin" {
			return nil
		}
		setProcess(s)
		setAdditionalGids := func(root string) error {
			var username string
			var primaryGID int
			uid, err := strconv.Atoi(userstr)
			if err == nil {
				user, err := UserFromPath(root, func(u *User) bool {
					return u.Uid == uid
				})
				if err != nil {
					if os.IsNotExist(err) || err == ErrNoUsersFound {
						s.Process.User.AdditionalGids = []uint32{}
						return nil
					}
					return err
				}
				username = user.Name
				primaryGID = user.Gid
			} else {
				username = userstr
				user, err := UserFromPath(root, func(u *User) bool {
					return u.Name == username
				})
				if err == nil {
					primaryGID = user.Gid
				}
			}
			gids, err := getSupplementalGroupsFromPath(root, func(g *Group) bool {
				// we only want supplemental groups
				if g.Name == username {
					return false
				}
				for _, entry := range g.List {
					if entry == username {
						return true
					}
				}
				return false
			})
			if err != nil {
				if os.IsNotExist(err) {
					// Clear supplementary groups if none found
					s.Process.User.AdditionalGids = []uint32{}
					return nil
				}
				return err
			}
			// Remove primary GID from supplementary groups if present
			var filteredGids []uint32
			for _, gid := range gids {
				if int(gid) != primaryGID {
					filteredGids = append(filteredGids, gid)
				}
			}
			s.Process.User.AdditionalGids = filteredGids
			return nil
		}
		if c.Snapshotter == "" && c.SnapshotKey == "" {
			if !isRootfsAbs(s.Root.Path) {
				return errors.New("rootfs absolute path is required")
			}
			return setAdditionalGids(s.Root.Path)
		}
		if c.Snapshotter == "" {
			return errors.New("no snapshotter set for container")
		}
		if c.SnapshotKey == "" {
			return errors.New("rootfs snapshot not created for container")
		}
		snapshotter := client.SnapshotService(c.Snapshotter)
		mounts, err := snapshotter.Mounts(ctx, c.SnapshotKey)
		if err != nil {
			return err
		}

		mounts = tryReadonlyMounts(mounts)
		return mount.WithTempMount(ctx, mounts, setAdditionalGids)
	}
}

