func (a *AuthenticatorOAuth2Introspection) tokenFromCache(config *AuthenticatorOAuth2IntrospectionConfiguration, token string, scopes []string, audience []string, issuers []string) (*AuthenticatorOAuth2IntrospectionResult, bool) {
	if !config.Cache.Enabled {
		return nil, false
	}

	cacheKey := generateCacheKey(token, scopes, audience, issuers)
	item, found := a.tokenCache.Get(cacheKey)
	if !found {
		return nil, false
	}

	i := item.(*AuthenticatorOAuth2IntrospectionResult)
	expires := time.Unix(i.Expires, 0)
	if expires.Before(time.Now()) {
		a.tokenCache.Del(cacheKey)
		return nil, false
	}

	return i, true
}

// generateCacheKey creates a unique cache key based on token, scopes, audience, and issuers
func generateCacheKey(token string, scopes []string, audience []string, issuers []string) string {
	return fmt.Sprintf("%s|scopes:%s|aud:%s|iss:%s", token, strings.Join(scopes, ","), strings.Join(audience, ","), strings.Join(issuers, ","))
}

