            else:
                # Check for dangerous calls in assignment value
                if is_dangerous_call(node.value):
                    continue
                new_body.append(node)
            continue
        # Block dangerous calls in Expr nodes
        if isinstance(node, ast.Expr):
            if is_dangerous_call(node.value):
                continue
            new_body.append(node)
            continue
        # Block DataFrame overwrites
        if self._is_df_overwrite(node):
            continue
        # For other nodes, allow only safe types
        if isinstance(node, (ast.Pass, ast.Break, ast.Continue)):
            new_body.append(node)
            continue
        # For other statement types, skip
        continue

    new_tree = ast.Module(body=new_body, type_ignores=[])
    return astor.to_source(new_tree, pretty_source=lambda x: "".join(x)).strip()

