	u, err := url.Parse(settings.URL + query.Path)
	if err != nil {
		return nil, err
	}

	// we need to verify that `query.Path` did not modify the hostname by doing tricks
	settingsURL, err := url.Parse(settings.URL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL")
