	if pathURL.IsAbs() || pathURL.Host != "" || pathURL.Scheme != "" {
		return nil, fmt.Errorf("query.Path must be a relative path and not contain scheme or host")
	}

	// Safely join base URL and path
	finalURL := *baseURL
	if pathURL.Path != "" {
		if strings.HasSuffix(finalURL.Path, "/") {
			finalURL.Path = finalURL.Path + strings.TrimLeft(pathURL.Path, "/")
		} else {
			finalURL.Path = finalURL.Path + pathURL.Path
		}
	}

	params := make(url.Values)
	for _, p := range query.Params {
