func hostMatchesGlob(host string, domainGlob string) bool {
	hostNorm := strings.ToLower(strings.TrimSuffix(host, "."))
	domainGlobNorm := strings.ToLower(strings.TrimSuffix(domainGlob, "."))

	if domainGlobNorm != "" && domainGlobNorm[0] == '*' {
		suffix := domainGlobNorm[1:]
		if strings.HasSuffix(hostNorm, suffix) {
			return true
		}
	} else if domainGlobNorm == hostNorm {
		return true
	}
	return false
}

