func RequireSignedJWT(ctx context.Context, key []byte) error {
	if len(key) > 0 {
		rawjwt, ok := JWTFromGRPCRequest(ctx)
		if !ok {
			return status.Error(codes.Unauthenticated, "unauthenticated")
		}

		tok, err := jwt.ParseSigned(rawjwt)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		var claims struct {
			Expiry    *jwt.NumericDate `json:"exp,omitempty"`
			Audience  jwt.Audience     `json:"aud,omitempty"`
			TokenType string           `json:"typ,omitempty"`
		}
		err = tok.Claims(key, &claims)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		if claims.Expiry == nil || time.Now().After(claims.Expiry.Time()) {
			return status.Errorf(codes.Unauthenticated, "expired JWT: %v", err)
		}

		// Ensure the audience matches the expected databroker API audience
		const expectedAudience = "pomerium-databroker"
		if !claims.Audience.Contains(expectedAudience) {
			return status.Errorf(codes.PermissionDenied, "invalid JWT audience")
		}

		// Ensure the token type is not a service account token
		if claims.TokenType == "service_account" {
			return status.Errorf(codes.PermissionDenied, "service account tokens are not authorized for databroker API access")
		}
	}
	return nil
}

