func (fs *Filesystem) Delete(p string) error {
	wg := sync.WaitGroup{}
	resolved := fs.unsafeFilePath(p)
	if !fs.unsafeIsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	// Block any whoopsies.
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	st, err := os.Lstat(resolved)
	if err != nil {
		if !os.IsNotExist(err) {
			fs.error(err).Warn("error while attempting to stat file before deletion")
		}
		return err
	}

	// If the target is a symlink, only delete the symlink itself, not the file it points to.
	if st.Mode()&os.ModeSymlink != 0 {
		// Ensure the symlink itself is inside the data directory
		if !fs.unsafeIsInDataDirectory(resolved) {
			return NewBadPathResolution(p, resolved)
		}
		return os.Remove(resolved)
	}

	if !st.IsDir() {
		fs.addDisk(-st.Size())
	} else {
		// For directories, recursively check for symlinks and prevent deletion if any symlink resolves outside the data directory
		var checkSymlinks func(string) error
		checkSymlinks = func(dir string) error {
			entries, err := os.ReadDir(dir)
			if err != nil {
				return err
			}
			for _, entry := range entries {
				entryPath := filepath.Join(dir, entry.Name())
				info, err := os.Lstat(entryPath)
				if err != nil {
					return err
				}
				if info.Mode()&os.ModeSymlink != 0 {
					linkTarget, err := os.Readlink(entryPath)
					if err != nil {
						return err
					}
					absTarget := linkTarget
					if !filepath.IsAbs(linkTarget) {
						absTarget = filepath.Join(filepath.Dir(entryPath), linkTarget)
					}
					if !fs.unsafeIsInDataDirectory(absTarget) {
						return NewBadPathResolution(entryPath, absTarget)
					}
				}
				if info.IsDir() {
					if err := checkSymlinks(entryPath); err != nil {
						return err
					}
				}
			}
			return nil
		}
		if err := checkSymlinks(resolved); err != nil {
			return err
		}
		wg.Add(1)
		go func(wg *sync.WaitGroup, st os.FileInfo, resolved string) {
			defer wg.Done()
			if s, err := fs.DirectorySize(resolved); err == nil {
				fs.addDisk(-s)
			}
		}(&wg, st, resolved)
	}

	wg.Wait()

	return os.RemoveAll(resolved)
}

