		return NewBadPathResolution(p, resolved)
	}

	// Block any whoopsies.
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	st, err := os.Lstat(resolved)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		fs.error(err).Warn("error while attempting to stat file before deletion")
		return err
	}

	// Helper function to recursively check for symlinks that resolve outside the data directory
	var checkSymlinks func(string) error
	checkSymlinks = func(path string) error {
		info, err := os.Lstat(path)
		if err != nil {
			if os.IsNotExist(err) {
				return nil
			}
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			linkTarget, err := os.Readlink(path)
			if err != nil {
				return err
			}
			absTarget := linkTarget
			if !filepath.IsAbs(linkTarget) {
				absTarget = filepath.Join(filepath.Dir(path), linkTarget)
			}
			absTarget, err = filepath.EvalSymlinks(absTarget)
			if err != nil {
				// If the symlink target does not exist, still check the intended path
				absTarget = filepath.Clean(absTarget)
			}
			if !fs.unsafeIsInDataDirectory(absTarget) {
				return NewBadPathResolution(path, absTarget)
			}
			// Only delete the symlink itself, not the target
			if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
				return err
			}
			return nil
		}
		if info.IsDir() {
			entries, err := os.ReadDir(path)
			if err != nil {
				return err
			}
			for _, entry := range entries {
				entryPath := filepath.Join(path, entry.Name())
				if err := checkSymlinks(entryPath); err != nil {
					return err
				}
			}
		}
		return nil
	}

	// If the target is a symlink, only delete the symlink itself
	if st.Mode()&os.ModeSymlink != 0 {
		// Ensure the symlink itself is inside the data directory
		if !fs.unsafeIsInDataDirectory(resolved) {
			return NewBadPathResolution(p, resolved)
		}
		return os.Remove(resolved)
	}

	// For directories, recursively check for symlinks and prevent deletion if any symlink resolves outside the data directory
	if st.IsDir() {
		if err := checkSymlinks(resolved); err != nil {
			return err
		}
		wg.Add(1)
		go func(wg *sync.WaitGroup, st os.FileInfo, resolved string) {
			defer wg.Done()
			if s, err := fs.DirectorySize(resolved); err == nil {
				fs.addDisk(-s)
			}
		}(&wg, st, resolved)
	} else {
		fs.addDisk(-st.Size())
	}

	wg.Wait()

	return os.RemoveAll(resolved)
}

