function compileObjectNode(node, defs, args) {
  if (!(node instanceof ObjectNode)) {
    throw new TypeError('No valid ObjectNode')
  }

  var entries = [];
  for (var key in node.properties) {
    if (hasOwnProperty(node.properties, key)) {
      // Normalize and sanitize property name to prevent Unicode spoofing
      var normalizedKey = key.normalize('NFC').replace(/[\u200B-\u200D\uFEFF]/g, ''); // Remove zero-width and invisible chars
      if (!isSafeProperty(node.properties, normalizedKey)) {
        throw new Error('No access to property "' + normalizedKey + '"');
      }
      entries.push(stringify(normalizedKey) + ': ' + compile(node.properties[key], defs, args));
    }
  }
  return '{' + entries.join(', ') + '}';
}

