const path = require('path');

function buildURL (source, reqBase) {
  // If no base is specified, return URL constructed from source only
  if (!reqBase) {
    try {
      return new URL(source);
    } catch (e) {
      throw new Error('Invalid URL');
    }
  }

  // Only allow relative paths as source
  if (typeof source !== 'string' || source.startsWith('http://') || source.startsWith('https://') || source.startsWith('//') || source.startsWith('urn:') || path.isAbsolute(source)) {
    throw new Error('source must be a relative path string');
  }

  const baseURL = new URL(reqBase);
  // Construct destination URL
