def allow_token(self, token):
    """Handles the case where we're allowing the tag"""
    if 'data' in token:
        # Loop through all the attributes and drop the ones that are not
        # allowed, are unsafe or break other rules. Additionally, fix
        # attribute values that need fixing.
        #
        # At the end of this loop, we have the final set of attributes
        # we're keeping.
        attrs = {}
        for namespaced_name, val in token['data'].items():
            namespace, name = namespaced_name

            # Drop attributes that are not explicitly allowed
            #
            # NOTE(willkg): We pass in the attribute name--not a namespaced
            # name.
            if not self.attr_filter(token['name'], name, val):
                continue

            # Look at attributes that have uri values
            if namespaced_name in self.attr_val_is_uri:
                val_unescaped = re.sub(
                    "[\`\000-\040\177-\240\s]+",
                    '',
                    unescape(val)).lower()

                # Remove replacement characters from unescaped characters.
                val_unescaped = val_unescaped.replace("\ufffd", "")

                # Always allow anchor links (e.g., href="#foo")
                if val.strip().startswith('#'):
                    pass  # Always allowed
                else:
                    # Strict protocol check: only allow if the value starts with an allowed protocol
                    match = re.match(r'^([a-z0-9][-+.a-z0-9]*):', val_unescaped)
                    if match:
                        proto = match.group(1)
                        if proto not in self.allowed_protocols:
                            continue
                    else:
                        # No explicit protocol, allow if allowed_protocols includes 'http' and value is a valid domain, localhost, or IP
                        if 'http' in self.allowed_protocols:
                            # Accept domain, localhost, or IP address (with optional port)
                            if not re.match(r'^(?:[a-zA-Z0-9.-]+|localhost|\d{1,3}(?:\.\d{1,3}){3})(?::\d+)?(?:/.*)?$', val_unescaped):
                                continue
                        else:
                            continue

