resolve: function resolve(hostname) {
    var output,
        nodeBinary = process.execPath,
        scriptPath = path.join(__dirname, "../scripts/dns-lookup-script"),
        response;

    // Validate hostname: only allow letters, digits, hyphens, and dots
    if (!/^[a-zA-Z0-9.-]+$/.test(hostname)) {
        debug('hostname', "Invalid hostname input: " + hostname);
        return null;
    }

    // Use spawnSync to avoid shell command injection
    var spawn = require('child_process').spawnSync;
    var result = spawn(nodeBinary, [scriptPath, hostname], {encoding: 'utf8'});
    if (result && result.status === 0) {
        output = result.stdout.trim();
        if (output && net.isIP(output)) {
            return output;
        }
    }
    debug('hostname', "fail to resolve hostname " + hostname);
    return null;
}

