func PDFHasImage(path string) bool {
	// Execute pdffonts -l 5 <path>
	cmd := exec.Command("pdffonts", "-l", "5", path)
	out, err := cmd.Output()
	if err != nil {
		log.Println(err)
		return false
	}
	// Process output: tail -n +3 | cut -d' ' -f1 | sort | uniq
	lines := strings.Split(string(out), "\n")
	if len(lines) <= 2 {
		return true
	}
	var fontNames []string
	for _, line := range lines[2:] {
		fields := strings.Fields(line)
		if len(fields) > 0 {
			fontNames = append(fontNames, fields[0])
		}
	}
	uniqueFonts := make(map[string]struct{})
	for _, name := range fontNames {
		uniqueFonts[name] = struct{}{}
	}
	if len(uniqueFonts) == 0 {
		return true
	}
	return false
}

