trimvideo: (input, start, duration, output) => {
  const fs = require('fs');
  const { spawn } = require('child_process');
  const path = require('path');

  // Basic validation and sanitization
  function isSafePath(p) {
    // Only allow relative or absolute paths without shell metacharacters
    return typeof p === 'string' && /^[\w\-.\/\\]+$/.test(p);
  }
  function isSafeNumber(n) {
    // Only allow numbers (integer or float)
    return typeof n === 'string' && /^\d+(\.\d+)?$/.test(n);
  }
  function isSafeOutputName(name) {
    // Only allow safe file names
    return typeof name === 'string' && /^[\w\-.]+$/.test(name);
  }

  return new Promise(function(resolve, reject) {
    if (!isSafePath(input) || !isSafeNumber(start) || !isSafeNumber(duration) || !isSafeOutputName(output)) {
      reject(new Error('Invalid input parameters'));
      return;
    }
    if (fs.existsSync(input)) {
      const outputFile = output + '.mp4';
      const ffmpegArgs = [
        '-hide_banner',
        '-loglevel', 'quiet',
        '-ss', start,
        '-i', input,
        '-t', duration,
        '-c', 'copy',
        '-y', outputFile
      ];
      const ffmpeg = spawn('ffmpeg', ffmpegArgs);
      let stderr = '';
      ffmpeg.stderr.on('data', (data) => {
        stderr += data.toString();
      });
      ffmpeg.on('error', (error) => {
        reject(error);
      });
      ffmpeg.on('close', (code) => {
        if (code !== 0) {
          reject(new Error(stderr || 'ffmpeg exited with code ' + code));
        } else {
          resolve(outputFile);
        }
      });
    } else {
      reject(new Error('ffmpegdotjs could not find file'));
    }
  });
}

