    const GIT_RE = /(^(git@|http(s)?:\/\/)([\w\.\-@]+)(\/|:))(([\~,\.\w,\-,\_,\/]+)(.git){0,1}((\/){0,1}))/;
    const PRIVATE_HOSTS = [
        'localhost',
        '127.0.0.1',
        '0.0.0.0',
        '::1'
    ];
    const PRIVATE_IP_RANGES = [
        /^127\./, // Loopback
        /^10\./, // Private
        /^192\.168\./, // Private
        /^172\.(1[6-9]|2[0-9]|3[0-1])\./, // Private
        /^169\.254\./ // Link-local
    ];
    const MAX_URL_LENGTH = 2048;

    if (typeof url !== "string" || !url.trim()) {
        const err = new Error("Invalid url.");
        err.subject_url = url;
        err.parse_failed = true;
        throw err;
    }
    if (url.length > MAX_URL_LENGTH) {
        const err = new Error("Input exceeds maximum length.");
        err.subject_url = url;
        err.parse_failed = true;
        throw err;
    }

    if (normalize) {
        if (typeof normalize !== "object") {
            normalize = {
                stripHash: false
            };
        }
        url = normalizeUrl(url, normalize);
    }

    let parsed;
    try {
        parsed = parsePath(url);
    } catch (e) {
        const err = new Error("URL parsing failed.");
        err.subject_url = url;
        err.parse_failed = true;
        throw err;
    }

    // Potential git-ssh urls
    if (parsed.protocol === "file") {
        const matched = parsed.href.match(GIT_RE);
        if (matched) {
            parsed.protocols = ["ssh"];
            parsed.protocol = "ssh";
            parsed.resource = matched[4];
            parsed.host = matched[4];
            parsed.user = "git";
            parsed.pathname = `/${matched[6]}`;
        }
    }

    // SSRF protection: block private/loopback hosts
    const host = parsed.host || parsed.resource;
    if (host) {
        const lowerHost = host.toLowerCase();
        if (PRIVATE_HOSTS.includes(lowerHost)) {
            const err = new Error("SSRF protection: URL host is a private or loopback address.");
            err.subject_url = url;
            err.parse_failed = true;
            throw err;
        }
        for (const re of PRIVATE_IP_RANGES) {
            if (re.test(lowerHost)) {
                const err = new Error("SSRF protection: URL host is a private or loopback IP address.");
                err.subject_url = url;
                err.parse_failed = true;
                throw err;
            }
        }
        // IPv6 loopback
        if (lowerHost === '::1') {
            const err = new Error("SSRF protection: URL host is a private or loopback IPv6 address.");
            err.subject_url = url;
            err.parse_failed = true;
            throw err;
        }
    }

    parsed.parse_failed = false;
    return parsed;
}

