def detectNFTables():
    # Use a dedicated safe_exec binary to restrict command execution
    safe_exec_path = "/usr/local/bin/safe_exec"
    if not os.path.isfile(safe_exec_path) or not os.access(safe_exec_path, os.X_OK):
        print("[-] safe_exec binary not available or not executable.")
        return False
    try:
        output = subprocess.check_output([safe_exec_path, "iptables", "--version"])
        return b"nf_tables" in output
    except Exception as e:
        print("[-] Error executing safe_exec: %s" % e)
        return False

